/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Exports
 *   Types: SaveOptions, SavePreferences
 *   Functions: useAutoSave
 * Internal
 *   Functions: same
 *   Constants: groups
 * @end-catalog */

import {useEffect, useRef, useState} from 'react';
import {ResearchPreferences} from '../types';

export interface SaveOptions {
  /** Set when the page is being hidden or closed, so a network save outlives the page. */
  keepalive?: boolean;
}

export type SavePreferences = (changes: ResearchPreferences, options?: SaveOptions) => Promise<void>;

const same = (a: unknown, b: unknown) => JSON.stringify(a) === JSON.stringify(b);

/** Fields that are only meaningful (and only valid) together, so a change to one always sends the group. */
const groups = [['keywords', 'useKeywordPrefix'], ['includeVideos', 'includeArticles']];

/**
 * Saves the form like a game save: shortly after a valid choice changes, only the changed fields are written.
 * `baseline` is what is already on disk (it may differ from the form when an earlier save failed or is still
 * in flight; those fields are then saved again). A change made while a save is in flight, including changing
 * a field back, is written when that save settles, or at once if the page is being hidden. A failed save is
 * retried with the next change, when the page is hidden, or when the form closes — never in a loop.
 */
export const useAutoSave = (preferences: ResearchPreferences, save: SavePreferences | undefined,
  delay: number | ((changes: ResearchPreferences) => number) = 400, baseline: ResearchPreferences = preferences) => {
  const [error, setError] = useState('');
  const latest = useRef(preferences);
  latest.current = preferences;
  // What is on disk or on its way there, and what a save has actually confirmed.
  const sent = useRef<Record<string, unknown>>({...baseline});
  const confirmed = useRef<Record<string, unknown>>({...baseline});
  const saveRef = useRef(save);
  saveRef.current = save;
  const inFlight = useRef(0);
  const changedDuringFlight = useRef(false);
  const failed = useRef(false);
  const mounted = useRef(true);
  const timer = useRef<number | undefined>(undefined);

  const wait = (patch: ResearchPreferences) => typeof delay === 'function' ? delay(patch) : delay;

  const changes = (): ResearchPreferences | null => {
    const current = latest.current as Record<string, unknown>;
    const patch: Record<string, unknown> = {};
    for (const [key, value] of Object.entries(current)) {
      if (!same(value, sent.current[key])) patch[key] = value;
    }
    for (const group of groups) {
      if (group.some((key) => key in patch) && group.every((key) => current[key] !== undefined)) {
        for (const key of group) patch[key] = current[key];
      }
    }
    return Object.keys(patch).length ? patch as ResearchPreferences : null;
  };

  // The only place that starts the debounce timer, so an earlier timer can never fire behind a newer one.
  const schedule = (ms: number) => {
    window.clearTimeout(timer.current);
    timer.current = window.setTimeout(() => flush(), ms);
  };

  const flush = (options: SaveOptions = {}) => {
    window.clearTimeout(timer.current);
    if (!saveRef.current) return;
    // A normal flush waits for the save in flight; a page being hidden cannot wait and sends its own save.
    if (inFlight.current > 0 && !options.keepalive) {
      changedDuringFlight.current = changedDuringFlight.current || Boolean(changes());
      return;
    }
    const patch = changes();
    if (!patch) return;
    inFlight.current += 1;
    changedDuringFlight.current = false;
    sent.current = {...sent.current, ...patch};
    saveRef.current(patch, options).then(() => {
      confirmed.current = {...confirmed.current, ...patch};
      failed.current = false;
      if (mounted.current) setError('');
    }, (reason: unknown) => {
      for (const key of Object.keys(patch)) {
        if (same(sent.current[key], (patch as Record<string, unknown>)[key])) sent.current[key] = confirmed.current[key];
      }
      failed.current = true;
      if (mounted.current) setError(reason instanceof Error ? reason.message : String(reason));
    }).finally(() => {
      inFlight.current -= 1;
      if (inFlight.current > 0) return;
      // After a failure, only a change made meanwhile is sent again; otherwise wait for the next change.
      const next = changes();
      if (!next || (failed.current && !changedDuringFlight.current)) return;
      if (mounted.current) schedule(wait(next));
      else flush();
    });
  };

  const key = JSON.stringify(preferences);
  useEffect(() => {
    const patch = changes();
    if (!patch) {
      // Changing a field back to its saved value clears an earlier failure.
      if (inFlight.current === 0) setError('');
      return;
    }
    if (inFlight.current > 0) changedDuringFlight.current = true;
    failed.current = false;
    schedule(wait(patch));
    return () => window.clearTimeout(timer.current);
  }, [key]);

  useEffect(() => {
    mounted.current = true;
    const hidden = () => flush({keepalive: true});
    const visibility = () => {
      if (document.visibilityState === 'hidden') hidden();
    };
    window.addEventListener('pagehide', hidden);
    document.addEventListener('visibilitychange', visibility);
    return () => {
      window.removeEventListener('pagehide', hidden);
      document.removeEventListener('visibilitychange', visibility);
      mounted.current = false;
      // Leaving the form (for example by starting the research) must not drop the last change.
      flush();
    };
  }, []);

  return error;
};
